INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-titas-gas-bill-correction-name-change', 'নতুন মালিকের জাতীয় পরিচয়পত্র (NID) কপি', 1, 0, 'ফটোকপি', 'প্রাসঙ্গিক সরকারি অফিস বা নিজস্ব সংরক্ষিত নথি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-titas-gas-bill-correction-name-change', 'ফ্ল্যাট বা বাড়ির রেজিস্ট্রিকৃত সাফ-কবলা দলিল ও নামজারি খতিয়ান', 1, 0, 'ফটোকপি ও আসল কপি প্রদর্শন', 'প্রাসঙ্গিক সরকারি অফিস বা নিজস্ব সংরক্ষিত নথি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-titas-gas-bill-correction-name-change', 'সর্বশেষ পরিশোধিত গ্যাস বিলের মূল কপি (কোনো বকেয়া থাকা যাবে না)', 1, 0, 'ব্যাংক সিলযুক্ত রসিদ', 'প্রাসঙ্গিক সরকারি অফিস বা নিজস্ব সংরক্ষিত নথি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-titas-gas-bill-correction-name-change', '২০০ টাকার নন-জুডিশিয়াল স্ট্যাম্পে অঙ্গীকারনামা', 1, 0, 'হলফনামা', 'প্রাসঙ্গিক সরকারি অফিস বা নিজস্ব সংরক্ষিত নথি');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-titas-gas-bill-correction-name-change', 1, 'তিতাস জোনাল অফিসে নির্ধারিত ফর্মে আবেদন', 'সংশ্লিষ্ট তিতাস রাজস্ব শাখায় গিয়ে ''নাম পরিবর্তন ফরম'' সংগ্রহ করুন। দলিলের ফটোকপি ও বকেয়াহীন বিলের কপি সংযুক্ত করুন।', 'https://titasgas.org.bd', 'আগের মালিকের কোনো বকেয়া বিল থাকলে তা আগেই ক্লিয়ার করতে হবে।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-titas-gas-bill-correction-name-change', 2, '৫০০ টাকা সরকারি ফি জমা ও শুনানি', 'ব্যাংক বুথে ৫০০ টাকার রসিদ জমা দিন। রাজস্ব কর্মকর্তা দলিল যাচাই করে মূল নথিতে নতুন মালিকের নাম আপডেট করবেন।', 'https://titasgas.org.bd', 'পরবর্তী মাস থেকেই নতুন মালিকের নামে গ্যাস বিল আসবে।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-titas-gas-bill-correction-name-change', 3, 'তদন্ত সম্পন্ন ও সংশোধিত বিল/নামজারি অনুমোদন', 'তিতাস গ্যাস আঞ্চলিক বিপণন কার্যালয়ের পরিদর্শক সরেজমিন যাচাই ও গ্যাস রাইজার চেক করবেন। অনুমোদন শেষে পরবর্তী মাস থেকে গ্রাহকের নামে সংশোধিত বিল জারি হবে।', 'https://titasgas.org.bd', 'অনুমোদনের কপিটি সযত্নে সংরক্ষণ করুন যাতে ভবিষ্যতে মালিকানা হস্তান্তরে কাজে লাগে।');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 'যাত্রী টিকিট বা লঞ্চের ভ্রমণ টিকিট', 1, 0, 'টিকিট', 'প্রাসঙ্গিক সরকারি অফিস বা নিজস্ব সংরক্ষিত নথি');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 'যাত্রীর জাতীয় পরিচয়পত্র (NID) বা পরিচয়পত্র (বয়স্ক/ছাত্র ছাড়ের ক্ষেত্রে)', 0, 0, 'পরিচয়পত্র প্রদর্শন', 'নিজস্ব এনআইডি বা স্টুডেন্ট কার্ড');
INSERT INTO service_documents (service_id, name, is_mandatory, attestation_required, format_type, how_to_obtain) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 'টোল জমার অফিশিয়াল ইজারাদার রসিদ কপি (চাঁদাবাজি প্রমাণে)', 1, 0, 'মূল রসিদ', 'ঘাট কাউন্টার');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 1, 'টার্মিনাল বা ঘাটের নোটিশ বোর্ডে সরকারি রেট চার্ট দেখা', 'প্রতিটি অনুমোদিত ঘাটে বিআইডব্লিউটিএ-এর অনুমোদিত টোল চার্ট টাঙানো থাকা বাধ্যতামূলক। চার্টের বেশি এক পয়সাও দেবেন না।', 'https://biwta.gov.bd', 'ইজারাদাররা ইচ্ছামতো ১০-২০ টাকা চাইলে প্রতিবাদ করুন।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 2, 'গেট পাস বা টোল টিকিট সংগ্রহ', '৫ টাকার সরকারি টিকিট কেটে টার্মিনালে প্রবেশ করুন এবং টিকিটটি নিজের কাছে রাখুন।', 'https://biwta.gov.bd', 'কুলি বা লেবার জোর করে মালামাল টেনে টাকা দাবি করতে পারে না।');
INSERT INTO service_steps (service_id, step_number, title, description, action_url, tips) VALUES ('bd-biwta-river-ghat-passenger-toll-rates', 3, 'অতিরিক্ত চাঁদাবাজির বিরুদ্ধে অভিযোগ', 'অতিরিক্ত অর্থ দাবি করলে ঘাটে দায়িত্বরত নৌ পুলিশ বা বিআইডব্লিউটিএ পরিবহন পরিদর্শকের রুমে গিয়ে তাৎক্ষণিক অভিযোগ জানান।', 'https://biwta.gov.bd', 'দালাল এড়িয়ে সরাসরি আবেদন করুন।');